function login(flag){
  if(flag===undefined){
    try{ result=JSON.parse(source.getLoginInfo()||'{}'); }catch(e){ result={}; }
  }else{
    try{ source.putLoginInfo(JSON.stringify(result)); result=JSON.parse(source.getLoginInfo()||'{}'); }catch(e){ result={}; }
  }
  var email=String(result['邮箱']||'');
  var pwd=String(result['密码']||'');
  if(!email||!pwd){ java.longToast('请填写邮箱和密码'); throw '请填写邮箱和密码'; }
  var hh='';try{hh=String((JSON.parse(source.getVariable()||'{}')||{}).host||'').trim();}catch(e){}
  if(!hh){ try{ hh=String(result['线路']||'').trim(); }catch(e){} }
  if(!hh){ hh=(typeof host!=='undefined')?host:''; }
  if(hh.indexOf('http')!=0){ hh='http://'+hh; }
  var opt=JSON.stringify({method:'POST',body:JSON.stringify({email:email,password:pwd}),headers:{'Content-Type':'application/json'}});
  java.longToast('正在登录…');
  var resp=java.ajax(hh+'/legado/login,'+opt);
  var j=JSON.parse(resp);
  if(j && j.code==200 && j.data && j.data.token){
    var vv={};try{vv=JSON.parse(source.getVariable()||'{}');}catch(e){}
    vv.token=j.data.token; vv.host=hh;
    source.setVariable(JSON.stringify(vv));
    java.longToast('登录成功'+((j.data.user&&j.data.user.nickname)?('：'+j.data.user.nickname):''));
  }else{
    var em=(j&&j.msg)||'登录失败'; java.longToast(em); throw em;
  }
}

