function tocUrlOf(bu){ return host+'/legado/toc?url='+encodeURIComponent(bu); }

function contentUrlOf(cu){ return host+'/legado/content?url='+encodeURIComponent(cu)+'&fmt=legado'; }
function PLATNAME(p){ return String(p||'').replace(/\(VIP\)$/,''); }



function SRCLIST(j, tab){
  var out=['全部'];
  try{
    var a=(j&&j[tab])||[];
    for(var i=0;i<a.length;i++){ out.push(a[i].n + (a[i].v ? '(VIP)' : '')); }
  }catch(e){}
  if(out.length<2){ out.push('番茄'); }
  return out;
}
function SRCFG(src){
  var v={};
  try{ v=JSON.parse(src.getVariable()||'{}')||{}; }catch(e){ v={}; }
  var m=null;
  try{ m=src.getLoginInfoMap(); }catch(e){ m=null; }
  function pick(k,d){
    if(v[k]){ return String(v[k]); }
    if(m){ try{ var x=m.get(k); if(x){ return String(x); } }catch(e){} }
    return d;
  }
  var h=String(v.host||'').trim();
  if(!h && m){ try{ var lh=m.get('线路'); if(lh){ h=String(lh); } }catch(e){} }
  if(!h){ h=host; }
  if(h.indexOf('http')!=0){ h='http://'+h; }
  return { host:h, gender:pick('频道','男频'), platform:pick('平台','全部'), mode:pick('模式','小说') };
}
function SRSHOW(m, t){
  var j=this.java, s=this.source;
  var data={};
  try{ data=JSON.parse(s.getVariable()||'{}')||{}; }catch(e){ data={}; }
  data[t]=m;
  s.setVariable(JSON.stringify(data));
  j.refreshExplore();
}
